using UnityEngine;
using Newtonsoft.Json.Linq;
namespace FalloutPort {
public class PortWorldEffects:MonoBehaviour {
 readonly System.Collections.Generic.Dictionary<int,GameObject> missiles=new System.Collections.Generic.Dictionary<int,GameObject>();
 Material tracer;AudioClip pistol,rifle;float lastSound;
 static Vector3 P(JToken p){return new Vector3((float)p["x"],(float)p["y"],-(float)p["z"]);}
 void Awake(){tracer=Resources.Load<Material>("FalloutFX/Tracer");pistol=Resources.Load<AudioClip>("FalloutAudio/Effects/pistolsound1");rifle=Resources.Load<AudioClip>("FalloutAudio/Effects/hunting rifle sound");}
 public void Projectiles(JToken states){var ids=new System.Collections.Generic.HashSet<int>();foreach(var p in states){int id=(int)p["id"];ids.Add(id);if(!missiles.TryGetValue(id,out var o)){o=GameObject.CreatePrimitive(PrimitiveType.Sphere);o.name="World "+(string)p["kind"];Destroy(o.GetComponent<Collider>());o.layer=2;o.transform.localScale=Vector3.one*.12f;o.GetComponent<Renderer>().sharedMaterial=tracer;var trail=o.AddComponent<TrailRenderer>();trail.sharedMaterial=tracer;trail.time=.12f;trail.startWidth=.08f;trail.endWidth=0;missiles[id]=o;}o.transform.position=P(p["pos"]);}var remove=new System.Collections.Generic.List<int>();foreach(var pair in missiles)if(!ids.Contains(pair.Key)){if(pair.Value)Destroy(pair.Value);remove.Add(pair.Key);}foreach(int id in remove)missiles.Remove(id);}
 void OnDestroy(){foreach(var o in missiles.Values)if(o)Destroy(o);}
 public void Play(JObject data){string kind=(string)data["kind"];if(kind=="explosion"||kind=="blood"){var burstObject=new GameObject("World "+kind);burstObject.transform.position=P(data["pos"]);var particles=burstObject.AddComponent<ParticleSystem>();var main=particles.main;main.loop=false;main.duration=.5f;main.startLifetime=kind=="blood"?.35f:.8f;main.startSpeed=kind=="blood"?2:4;main.startSize=kind=="blood"?.04f:.3f;main.startColor=kind=="blood"?new Color(.45f,.015f,.015f):new Color(1,.4f,.05f);main.maxParticles=60;var emission=particles.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,(short)(kind=="blood"?12:45))});particles.GetComponent<ParticleSystemRenderer>().sharedMaterial=tracer;particles.Play();Destroy(burstObject,2);return;}if(kind=="tracer"||kind=="laser"){var line=new GameObject("World gunfire").AddComponent<LineRenderer>();line.sharedMaterial=tracer;line.positionCount=2;line.SetPosition(0,P(data["from"]));line.SetPosition(1,P(data["to"]));line.startWidth=kind=="laser"?.025f:.012f;line.endWidth=.004f;line.startColor=line.endColor=kind=="laser"?Color.red:new Color(1,.7f,.25f);Destroy(line.gameObject,.09f);return;}if(kind!="sound"||Time.time<lastSound)return;string sound=(string)data["name"];if(!(sound.Contains("gun")||sound.Contains("shot")||sound.Contains("rifle")))return;var clip=sound.Contains("rifle")?rifle:pistol;if(!clip)return;lastSound=Time.time+.035f;var o=new GameObject("World gunshot");o.transform.position=data["pos"]!=null?P(data["pos"]):GetComponent<PortGame>().player.transform.position;var audio=o.AddComponent<AudioSource>();audio.clip=clip;audio.spatialBlend=1;audio.minDistance=4;audio.maxDistance=120;audio.rolloffMode=AudioRolloffMode.Logarithmic;audio.volume=Mathf.Clamp01((float?)data["volume"]??.6f);audio.pitch=Mathf.Clamp((float?)data["pitch"]??1,.5f,2);audio.Play();Destroy(o,clip.length+1);}
}
}
